import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const scriptsDirectory = path.dirname(fileURLToPath(import.meta.url))
const projectDirectory = path.resolve(scriptsDirectory, '..')
const sourceFiles = [
  'src/game.js',
  'src/voyages.js',
  'src/lobby.js',
  'src/online-config.js',
  'src/online-room.js',
  'src/app.js',
]

function removeModuleSyntax(source, filename) {
  const withoutImports = source.replace(
    /^import\s+[\s\S]*?\s+from\s+['"][^'"]+['"]\s*\r?\n/gm,
    '',
  )
  const bundled = withoutImports.replace(
    /^export\s+(?=(?:const|let|var|function|class)\b)/gm,
    '',
  )
  if (/^(?:import|export)\s/m.test(bundled)) {
    throw new Error(`Unsupported module syntax remains in ${filename}`)
  }
  return bundled.trim()
}

const sections = []
for (const filename of sourceFiles) {
  const source = await readFile(path.join(projectDirectory, filename), 'utf8')
  sections.push(`// ${filename}\n${removeModuleSyntax(source, filename)}`)
}

const output = `// Generated by npm run build. Edit the source modules, not this file.
(() => {
'use strict'

${sections.join('\n\n')}
})()
`

await writeFile(path.join(projectDirectory, 'src/app.bundle.js'), output)
console.log('Built src/app.bundle.js')
